      'fallback_impulse_headline': 'Tagesimpuls für deinen Alltag',
      'fallback_understood_title': 'Kurz verstanden',
      'fallback_understood_summary':
          'Kinder kooperieren besser, wenn sie sich zuerst gesehen fühlen. Verbindung kommt vor Korrektur.',
      'fallback_evening_reflection': 'Abend-Reflexion',
      'fallback_default_reflection':
          'Was hat heute gut funktioniert? Welchen Moment mit deinem Kind willst du festhalten?',
      'duration_1_min': '1 Min.',
      'duration_2_min': '2 Min.',
